  const { branch = null, pr = null, merged = false } = delivered ?? {};
  if (!branch && !pr) return [];
  return [
    '### Delivered by code-work',
    'The artifacts this run created — the ones to work on.',
    '',
    ...(pr ? [`- PR: #${pr}${merged ? ' (already merged — open your own PR for further work)' : ' (open)'}`] : []),
