node --test test/queue/executor-loop.test.mjs 2>&1 | grep -E "^# (tests|pass|fail)|^not ok" | head -4

cd /home/user/claudinite/packs/claudinite-tasks && python3 - <<'PYEOF'
p='code-work.mjs'
s=open(p).read()
old = """// The kind is one of the triage kinds (`action`, `decision`, `approval`,
// `failure`); anything else, or no marker at all, leaves the park a `failure`."""
new = """// The kind is one of the triage kinds (`action`, `decision`, `approval`,
