  return {repo,num:+num,labels:(labels||'').split(',').filter(Boolean),title};
});

const KINDS=['failure','action','decision','approval'];
for (const r of rows) {
  const L=r.labels;
  r.isWork = r.title.startsWith('[claudinite-work]');
  r.queue  = r.isWork || L.some(x=>x.startsWith('task:')) || L.includes('needs-human') || L.includes('origin:schedule');
  r.canonStatus = L.find(x=>x.startsWith('task:status:'))?.replace('task:status:','') ?? null;
  const legacyKind = L.find(x=>/^task:needs-human-/.test(x))?.replace('task:needs-human-','') ?? null;
  r.legacy = !!legacyKind || L.includes('origin:schedule') || (L.includes('needs-human') && !r.canonStatus) || L.includes('task:blocked');
  r.kind = r.canonStatus && KINDS.includes(r.canonStatus.replace('needs-human-','')) ? r.canonStatus.replace('needs-human-','')
         : legacyKind && KINDS.includes(legacyKind) ? legacyKind : null;
  r.status = r.kind ? `park:${r.kind}`
    : r.canonStatus === 'blocked' || L.includes('task:blocked') || (L.includes('blocked') && r.queue) ? 'blocked'
    : r.canonStatus === 'waiting-for-executor' ? 'waiting-for-executor'
    : L.includes('needs-human') ? 'bare-needs-human'
    : r.queue ? 'no-status' : null;
  r.vocab = r.canonStatus ? 'canon' : r.legacy ? 'legacy' : '-';
}

const q = rows.filter(r=>r.queue);
const nonq = rows.filter(r=>!r.queue);
const tally=(arr,f)=>{const m=new Map();for(const r of arr){const k=f(r);m.set(k,(m.get(k)||0)+1);}return [...m].sort((a,b)=>b[1]-a[1]);};

console.log(`TOTAL open ${rows.length}   queue-managed ${q.length}   plain issues ${nonq.length}\n`);
console.log('== QUEUE ITEMS by status x vocabulary ==');
for(const [k,v] of tally(q,r=>`${r.status}\t${r.vocab}`)) console.log(`${String(v).padStart(4)}  ${k}`);
console.log('\n== PARKS by kind ==');
for(const [k,v] of tally(q.filter(r=>r.kind),r=>r.kind)) console.log(`${String(v).padStart(4)}  ${k}`);
console.log('\n== PARKS by kind x vocab ==');
for(const [k,v] of tally(q.filter(r=>r.kind),r=>`${r.kind}\t${r.vocab}`)) console.log(`${String(v).padStart(4)}  ${k}`);
console.log('\n== decision parks by task ==');
for(const [k,v] of tally(q.filter(r=>r.kind==='decision'),r=>r.title.replace('[claudinite-work] ','').slice(0,55))) console.log(`${String(v).padStart(4)}  ${k}`);
console.log('\n== queue items by repo ==');
for(const [k,v] of tally(q,r=>r.repo)) console.log(`${String(v).padStart(4)}  ${k}`);
console.log('\n== PLAIN ISSUES by primary label ==');
const prim=r=>['workflow-failure','add-packs','blocked','needs-decision','quick-win','plan-tracking','claude-queued','conformance-backlog','extractor-request'].find(l=>r.labels.includes(l))
  ?? (/^Claudinite tracker:/.test(r.title)?'(tracker)':/^\[claudinite-schedule\]/.test(r.title)?'(schedule board)':'(unlabelled)');
for(const [k,v] of tally(nonq,prim)) console.log(`${String(v).padStart(4)}  ${k}`);
EOF
